DROP TABLE IF EXISTS `item_tournament_link`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `item_tournament_link` (
  `tournament_entry` int unsigned NOT NULL COMMENT 'item_template.entry of the tournament-mode item',
  `world_entry` int unsigned DEFAULT NULL COMMENT 'item_template.entry of the world-mode item it stands for, NULL when it has none',
  `crunched` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '1 = the tournament side was retuned (lower item level, different stats), 0 = the same item on both sides',
  `source` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tmode' COMMENT 'how the pair was established: tmode = the 2026-09 tournament copy run, manual = added by hand',
  `comment` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`tournament_entry`),
  UNIQUE KEY `world_entry` (`world_entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Centurion: every tournament-mode item and the world-mode item it stands for';
/*!40101 SET character_set_client = @saved_cs_client */;

